class Dispatcher {
    std::vector<std::function<void(Event&)>> handlers_;
public:
    void on_event(std::function<void(Event&)> h) { handlers_.push_back(std::move(h)); }
    void run() { for (;;) for (auto& h : handlers_) h(next_event()); }   // it decides when
};
Dispatcher d;
d.on_event([](Event& e) { handle(e); });       // you only supply behaviour
d.run();

task<void> session(socket s) {                  // started by the framework
    for (;;) {
        auto data = co_await s.async_read();    // suspended; framework resumes you
        if (data.empty()) break;
        co_await s.async_write(process(data));
    }
}
server.set_handler([](socket s) { spawn(session(std::move(s))); });
server.run();
